 51	import io.javalin.Javalin;
 52	import org.json.JSONObject;
 53	import org.slf4j.Logger;
 54	import org.slf4j.LoggerFactory;
 55	
 56	import java.math.BigDecimal;
 57	import java.time.LocalDate;
 58	import java.time.format.DateTimeFormatter;
 59	
 60	public class ReservationApi {
 61	    private static final Logger log = LoggerFactory.getLogger(ReservationApi.class);
 62	    private static final ReservationRepository reservationRepo = new ReservationRepository();
 63	    private static final RoomRepository roomRepo = new RoomRepository();
 64	    private static final MessageRepository messageRepo = new MessageRepository();
 65	    private static final MessageService messageService = new MessageService(messageRepo);
 66	    private static final ReservationService reservationService = new ReservationService(reservationRepo, roomRepo, messageService);
 67	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 68	
 69	    public static void register(Javalin app) {
 70	        app.post("/reservations", ctx -> {
 71	            try {
 72	                JSONObject body = new JSONObject(ctx.body());
 73	
 74	                // Validate required fields
 75	                if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
 76	                    !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
 77	                    !body.has("guests") || !body.has("ratePlan")) {
 78	                    ctx.status(400).json(new JSONObject()
 79	                        .put("error", "INVALID_REQUEST")
 80	                        .put("message", "Missing required fields"));
 81	                    return;
 82	                }
 83	
 84	                int roomNumber = body.getInt("roomNumber");
 85	                String guestName = body.getString("guestName");
 86	                String guestEmail = body.getString("guestEmail");
 87	                String guestCpf = body.getString("guestCpf");
 88	                String checkInStr = body.getString("checkIn");
 89	                String checkOutStr = body.getString("checkOut");
 90	                int guests = body.getInt("guests");
 91	                String ratePlan = body.getString("ratePlan");
 92	                String companyCode = body.optString("companyCode", null);
 93	
 94	                LocalDate checkIn = LocalDate.parse(checkInStr, DATE_FORMAT);
 95	                LocalDate checkOut = LocalDate.parse(checkOutStr, DATE_FORMAT);
 96	
 97	                Reservation reservation = reservationService.create(roomNumber, guestName, guestEmail, guestCpf,
 98	                                                                   checkIn, checkOut, guests, ratePlan, companyCode);
 99	
100	                ctx.status(201).json(reservationToJson(reservation));
101	            } catch (ReservationService.ApiException e) {
102	                ctx.status(getStatusCode(e.getCode()))
103	                    .json(new JSONObject()
104	                        .put("error", e.getCode())
105	                        .put("message", e.getMessage()));
106	            } catch (Exception e) {
107	                log.error("Error creating reservation", e);
108	                ctx.status(400).json(new JSONObject()
109	                    .put("error", "INVALID_REQUEST")
110	                    .put("message", e.getMessage()));
111	            }
112	        });
113	
114	        app.get("/reservations/{id}", ctx -> {
115	            try {
116	                long id = Long.parseLong(ctx.pathParam("id"));
117	                Reservation reservation = reservationRepo.findById(id);
118	
119	                if (reservation == null) {
120	                    ctx.status(404).json(new JSONObject()
121	                        .put("error", "RESERVATION_NOT_FOUND")
122	                        .put("message", "Reservation not found"));
123	                    return;
124	                }
125	
126	                ctx.json(reservationToJson(reservation));
127	            } catch (Exception e) {
128	                log.error("Error retrieving reservation", e);
129	                ctx.status(500).json(new JSONObject().put("error", "INTERNAL_ERROR"));
130	            }
131	        });
132	
133	        app.post("/reservations/{id}/confirmation", ctx -> {
134	            try {
135	                long id = Long.parseLong(ctx.pathParam("id"));
136	                JSONObject body = new JSONObject(ctx.body());
137	
138	                if (!body.has("amountPaid")) {
139	                    ctx.status(400).json(new JSONObject()
140	                        .put("error", "INVALID_REQUEST")
141	                        .put("message", "Missing amountPaid"));
142	                    return;
143	                }
144	
145	                BigDecimal amountPaid = BigDecimal.valueOf(body.getDouble("amountPaid"));
146	                Reservation reservation = reservationService.confirm(id, amountPaid);
147	
148	                ctx.json(reservationToJson(reservation));
149	            } catch (ReservationService.ApiException e) {
150	                ctx.status(getStatusCode(e.getCode()))
151	                    .json(new JSONObject()
152	                        .put("error", e.getCode())
153	                        .put("message", e.getMessage()));
154	            } catch (Exception e) {
155	                log.error("Error confirming reservation", e);
156	                ctx.status(500).json(new JSONObject().put("error", "INTERNAL_ERROR"));
157	            }
158	        });
159	
160	        app.post("/reservations/{id}/cancellation", ctx -> {
161	            try {
162	                long id = Long.parseLong(ctx.pathParam("id"));
163	                Reservation reservation = reservationService.cancel(id);
164	
165	                ctx.json(reservationToJson(reservation));
166	            } catch (ReservationService.ApiException e) {
167	                ctx.status(getStatusCode(e.getCode()))
168	                    .json(new JSONObject()
169	                        .put("error", e.getCode())
170	                        .put("message", e.getMessage()));
171	            } catch (Exception e) {
172	                log.error("Error cancelling reservation", e);
173	                ctx.status(500).json(new JSONObject().put("error", "INTERNAL_ERROR"));
174	            }
175	        });
176	
177	        app.post("/reservations/{id}/check-in", ctx -> {
178	            try {
179	                long id = Long.parseLong(ctx.pathParam("id"));
180	                Reservation reservation = reservationService.checkIn(id);
181	
182	                ctx.json(reservationToJson(reservation));
183	            } catch (ReservationService.ApiException e) {
184	                ctx.status(getStatusCode(e.getCode()))
185	                    .json(new JSONObject()
186	                        .put("error", e.getCode())
187	                        .put("message", e.getMessage()));
188	            } catch (Exception e) {
189	                log.error("Error checking in reservation", e);
190	                ctx.status(500).json(new JSONObject().put("error", "INTERNAL_ERROR"));
191	            }
192	        });
193	
194	        app.post("/reservations/{id}/check-out", ctx -> {
195	            try {
196	                long id = Long.parseLong(ctx.pathParam("id"));
197	                Reservation reservation = reservationService.checkOut(id);
198	
199	                Reservation finalRes = reservationRepo.findById(id);
200	                Room room = roomRepo.findById(finalRes.getRoomNumber());
201	                String comprovante = ComprovantePrinter.generate(finalRes, room.getType().name());
202	
203	                JSONObject response = new JSONObject();
204	                response.put("title", "Comprovante de reserva");
205	                response.put("reservationId", finalRes.getId());
206	                response.put("guestName", finalRes.getGuestName());
207	                response.put("guestCpf", finalRes.getGuestCpf());
208	                response.put("roomNumber", finalRes.getRoomNumber());
209	                response.put("roomType", room.getType().name());
210	                response.put("checkIn", finalRes.getCheckIn());
211	                response.put("checkOut", finalRes.getCheckOut());
212	                response.put("nights", finalRes.getNights());
213	                response.put("subtotal", toDecimal(finalRes.getSubtotal()));
214	                response.put("discount", toDecimal(finalRes.getDiscount()));
215	                response.put("total", toDecimal(finalRes.getTotal()));
216	
217	                ctx.json(response);
218	            } catch (ReservationService.ApiException e) {
219	                ctx.status(getStatusCode(e.getCode()))
220	                    .json(new JSONObject()
221	                        .put("error", e.getCode())
222	                        .put("message", e.getMessage()));
223	            } catch (Exception e) {
224	                log.error("Error checking out reservation", e);
225	                ctx.status(500).json(new JSONObject().put("error", "INTERNAL_ERROR"));
226	            }
227	        });
228	
229	        app.get("/reservations/{id}/document", ctx -> {
230	            try {
231	                long id = Long.parseLong(ctx.pathParam("id"));
232	                Reservation reservation = reservationRepo.findById(id);
233	
234	                if (reservation == null) {
235	                    ctx.status(404).json(new JSONObject()
236	                        .put("error", "RESERVATION_NOT_FOUND")
237	                        .put("message", "Reservation not found"));
238	                    return;
239	                }
240	
241	                if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) <= 0) {
242	                    ctx.status(400).json(new JSONObject()
243	                        .put("error", "INVALID_REQUEST")
244	                        .put("message", "No paid reservation to print"));
245	                    return;
246	                }
247	
248	                Room room = roomRepo.findById(reservation.getRoomNumber());
249	
250	                JSONObject response = new JSONObject();
251	                response.put("title", "Comprovante de reserva");
252	                response.put("reservationId", reservation.getId());
253	                response.put("guestName", reservation.getGuestName());
254	                response.put("guestCpf", reservation.getGuestCpf());
255	                response.put("roomNumber", reservation.getRoomNumber());
256	                response.put("roomType", room.getType().name());
257	                response.put("checkIn", reservation.getCheckIn());
258	                response.put("checkOut", reservation.getCheckOut());
259	                response.put("nights", reservation.getNights());
260	                response.put("subtotal", toDecimal(reservation.getSubtotal()));
261	                response.put("discount", toDecimal(reservation.getDiscount()));
262	                response.put("total", toDecimal(reservation.getTotal()));
263	
264	                ctx.json(response);
265	            } catch (Exception e) {
266	                log.error("Error retrieving document", e);
267	                ctx.status(500).json(new JSONObject().put("error", "INTERNAL_ERROR"));
268	            }
269	        });
270	    }
271	
272	    private static JSONObject reservationToJson(Reservation res) {
273	        JSONObject json = new JSONObject();
274	        json.put("id", res.getId());
275	        json.put("roomNumber", res.getRoomNumber());
276	        json.put("guestName", res.getGuestName());
277	        json.put("guestEmail", res.getGuestEmail());
278	        json.put("guestCpf", res.getGuestCpf());
279	        json.put("checkIn", res.getCheckIn());
280	        json.put("checkOut", res.getCheckOut());
281	        json.put("guests", res.getGuests());
282	        json.put("ratePlan", res.getRatePlan());
283	        json.put("nights", res.getNights());
284	        json.put("subtotal", toDecimal(res.getSubtotal()));
285	        json.put("discount", toDecimal(res.getDiscount()));
286	        json.put("total", toDecimal(res.getTotal()));
287	        json.put("status", res.getStatus().name());
288	        json.put("amountPaid", toDecimal(res.getAmountPaid()));
289	        if (res.getRefund() != null) {
290	            json.put("refund", toDecimal(res.getRefund()));
291	        } else {
292	            json.put("refund", JSONObject.NULL);
293	        }
294	        return json;
295	    }
296	
297	    private static double toDecimal(BigDecimal value) {
298	        return Double.parseDouble(String.format("%.2f", value));
299	    }
300	
301	    private static int getStatusCode(String code) {
302	        return switch (code) {
303	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
304	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
305	            case "CAPACITY_EXCEEDED" -> 422;
306	            default -> 400;
307	        };
308	    }
309	}

