272	    private static JSONObject reservationToJson(Reservation res) {
273	        JSONObject json = new JSONObject();
274	        json.put("id", res.getId());
275	        json.put("roomNumber", res.getRoomNumber());
276	        json.put("guestName", res.getGuestName());
277	        json.put("guestEmail", res.getGuestEmail());
278	        json.put("guestCpf", res.getGuestCpf());
279	        json.put("checkIn", res.getCheckIn());
280	        json.put("checkOut", res.getCheckOut());
281	        json.put("guests", res.getGuests());
282	        json.put("ratePlan", res.getRatePlan());
283	        json.put("nights", res.getNights());
284	        json.put("subtotal", toDecimal(res.getSubtotal()));
285	        json.put("discount", toDecimal(res.getDiscount()));
286	        json.put("total", toDecimal(res.getTotal()));
287	        json.put("status", res.getStatus().name());
288	        json.put("amountPaid", toDecimal(res.getAmountPaid()));
289	        if (res.getRefund() != null) {
290	            json.put("refund", toDecimal(res.getRefund()));
291	        } else {
292	            json.put("refund", JSONObject.NULL);
293	        }
294	        return json;
295	    }
296	
297	    private static double toDecimal(BigDecimal value) {
298	        return Double.parseDouble(String.format("%.2f", value));
299	    }
300	
301	    private static int getStatusCode(String code) {
302	        return switch (code) {
303	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
304	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
305	            case "CAPACITY_EXCEEDED" -> 422;
306	            default -> 400;
307	        };
308	    }
309	}

