 30	    public Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
 31	                             LocalDate checkIn, LocalDate checkOut, int guests, String ratePlanName,
 32	                             String companyCode) throws Exception {
 33	        // Validation
 34	        if (guests < 1) {
 35	            throw new ApiException("INVALID_REQUEST", "At least one guest is required");
 36	        }
 37	
 38	        if (!checkOut.isAfter(checkIn)) {
 39	            throw new ApiException("INVALID_REQUEST", "Check-out must be after check-in");
 40	        }
 41	
 42	        Room room = roomRepo.findById(roomNumber);
 43	        if (room == null) {
 44	            throw new ApiException("ROOM_NOT_FOUND", "Room not found");
 45	        }
 46	
 47	        if (guests > room.getCapacity()) {
 48	            throw new ApiException("CAPACITY_EXCEEDED", "Guest count exceeds room capacity");
 49	        }
 50	
 51	        if (!RatePlanFactory.exists(ratePlanName)) {
 52	            throw new ApiException("INVALID_REQUEST", "Invalid rate plan");
 53	        }
 54	
 55	        // Check availability
 56	        if (!reservationRepo.isRoomAvailable(roomNumber, checkIn, checkOut)) {
 57	            throw new ApiException("ROOM_UNAVAILABLE", "Room is not available for these dates");
 58	        }
 59	
 60	        // Get rate plan and validate
 61	        RatePlan ratePlan = RatePlanFactory.getPlan(ratePlanName);
 62	        try {
 63	            ratePlan.validate(room, checkIn, checkOut, guests, companyCode);
 64	        } catch (RatePlan.RatePlanException e) {
 65	            throw new ApiException(e.getCode(), e.getMessage());
 66	        }
 67	
 68	        // Calculate price
 69	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 70	        RatePlan.PriceCalculation calc = ratePlan.calculatePrice(room, checkIn, checkOut);
 71	        BigDecimal subtotal = calc.subtotal();
 72	        BigDecimal discount = calc.discount();
 73	
 74	        // Apply company discount for CORPORATE plan
 75	        if ("CORPORATE".equals(ratePlanName)) {
 76	            CorporatePlan corporatePlan = (CorporatePlan) ratePlan;
 77	            BigDecimal companyDiscount = corporatePlan.getCompanyDiscount(companyCode);
 78	            discount = Money.percentage(subtotal, companyDiscount);
 79	        }
 80	
 81	        BigDecimal total = Money.subtract(subtotal, discount);
 82	
 83	        // Save reservation
