212	    public String generateOccupancyReport(LocalDate date) throws SQLException {
213	        StringBuilder csv = new StringBuilder();
214	        csv.append("room,type,reservation,check_in,check_out\n");
215	
216	        int occupiedCount = 0;
217	
218	        try (Connection conn = Database.getConnection()) {
219	            var stmt = conn.prepareStatement(
220	                """
221	                SELECT r.id, r.room_number, r.check_in, r.check_out
222	                FROM reservations r
223	                WHERE r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
224	                AND r.check_in <= ? AND r.check_out > ?
225	                ORDER BY r.room_number
226	                """
227	            );
228	            stmt.setDate(1, java.sql.Date.valueOf(date));
229	            stmt.setDate(2, java.sql.Date.valueOf(date));
230	
231	            ResultSet rs = stmt.executeQuery();
232	            while (rs.next()) {
233	                long reservationId = rs.getLong("id");
234	                int roomNumber = rs.getInt("room_number");
235	                LocalDate checkIn = rs.getDate("check_in").toLocalDate();
236	                LocalDate checkOut = rs.getDate("check_out").toLocalDate();
237	
238	                var room = roomRepo.findById(roomNumber);
239	                csv.append(roomNumber).append(",")
240	                    .append(room.getType()).append(",")
241	                    .append(reservationId).append(",")
242	                    .append(checkIn).append(",")
243	                    .append(checkOut).append("\n");
244	
245	                occupiedCount++;
246	            }
247	        }
248	
249	        int totalRooms = 5;
250	        csv.append("total,").append(occupiedCount).append("/").append(totalRooms).append("\n");
251	
252	        return csv.toString();
253	    }
254	
255	    public String generateRevenueReport(YearMonth month) throws SQLException {
256	        StringBuilder csv = new StringBuilder();
257	        csv.append("reservation,room,check_in,check_out,status,amount\n");
258	
259	        BigDecimal totalAmount = BigDecimal.ZERO;
260	
261	        try (Connection conn = Database.getConnection()) {
262	            var stmt = conn.prepareStatement(
263	                """
264	                SELECT id, room_number, check_in, check_out, status, amount_paid, refund
265	                FROM reservations
266	                WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ?
267	                AND (amount_paid > 0 OR refund > 0)
268	                ORDER BY check_in, id
269	                """
270	            );
271	            stmt.setInt(1, month.getYear());
272	            stmt.setInt(2, month.getMonthValue());
273	
274	            ResultSet rs = stmt.executeQuery();
275	            while (rs.next()) {
276	                long reservationId = rs.getLong("id");
277	                int roomNumber = rs.getInt("room_number");
278	                LocalDate checkIn = rs.getDate("check_in").toLocalDate();
279	                LocalDate checkOut = rs.getDate("check_out").toLocalDate();
280	                String status = rs.getString("status");
281	                BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
282	                BigDecimal refund = rs.getBigDecimal("refund");
283	
284	                BigDecimal netAmount = amountPaid;
285	                if (refund != null && refund.compareTo(BigDecimal.ZERO) > 0) {
286	                    netAmount = Money.subtract(amountPaid, refund);
287	                }
288	
289	                csv.append(reservationId).append(",")
290	                    .append(roomNumber).append(",")
291	                    .append(checkIn).append(",")
292	                    .append(checkOut).append(",")
293	                    .append(status).append(",")
294	                    .append(String.format("%.2f", netAmount)).append("\n");
295	
296	                totalAmount = Money.add(totalAmount, netAmount);
297	            }
298	        }
299	
300	        csv.append("total,")
301	            .append(String.format("%.2f", totalAmount)).append("\n");
302	
303	        return csv.toString();
304	    }
305	}
