222	                FROM reservations r
223	                WHERE r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
224	                AND r.check_in <= ? AND r.check_out > ?
225	                ORDER BY r.room_number
226	                """
227	            );
