258	
259	        BigDecimal totalAmount = BigDecimal.ZERO;
260	
261	        try (Connection conn = Database.getConnection()) {
262	            var stmt = conn.prepareStatement(
263	                """
264	                SELECT id, room_number, check_in, check_out, status, amount_paid, refund
265	                FROM reservations
266	                WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ?
267	                AND (amount_paid > 0 OR refund > 0)
268	                ORDER BY check_in, id
269	                """
270	            );
271	            stmt.setInt(1, month.getYear());
272	            stmt.setInt(2, month.getMonthValue());
