213	public class WeekendPackagePlan implements RatePlan {
214	    private static final Map<Room.Type, BigDecimal> PACKAGE_PRICES = Map.of(
215	            Room.Type.STANDARD, BigDecimal.valueOf(520.00),
216	            Room.Type.DELUXE, BigDecimal.valueOf(820.00),
217	            Room.Type.SUITE, BigDecimal.valueOf(1200.00)
