220	    @Override
221	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) throws RatePlanException {
222	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
223	            throw new RatePlanException("INVALID_REQUEST", "Weekend package must start on a Friday");
224	        }
225	
226	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
227	            throw new RatePlanException("INVALID_REQUEST", "Weekend package must end on a Sunday");
228	        }
229	
230	        long daysBetween = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
231	        if (daysBetween != 2) {
232	            throw new RatePlanException("INVALID_REQUEST", "Weekend package must be exactly 2 nights");
233	        }
234	    }
