236	    @Override
237	    public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut) {
238	        BigDecimal price = PACKAGE_PRICES.get(room.getType());
239	        return new PriceCalculation(price, BigDecimal.ZERO);
240	    }
