338	public class ComprovantePrinter {
339	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
340	
341	    public static String generate(Reservation reservation, String roomType) {
342	        StringBuilder sb = new StringBuilder();
343	
344	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
345	        sb.append("Hóspede: ").append(reservation.getGuestName())
346	            .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
347	        sb.append("Quarto: ").append(reservation.getRoomNumber())
348	            .append(" (").append(roomType).append(")\n");
349	
350	        sb.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMAT));
351	        sb.append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMAT));
352	        sb.append(" | ").append(formatNights(reservation.getNights())).append("\n");
353	
354	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
355	
356	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
357	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
358	        }
359	
360	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
361	
362	        return sb.toString();
363	    }
364	
365	    public static String formatMoney(BigDecimal value) {
366	        return String.format("R$ %.2f", value);
367	    }
368	
369	    public static String formatCpf(String cpf) {
370	        if (cpf.length() != 11) return cpf;
371	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
372	               cpf.substring(6, 9) + "-" + cpf.substring(9);
373	    }
374	
375	    private static String formatNights(int nights) {
376	        if (nights == 1) return "1 diária";
377	        return nights + " diárias";
378	    }
379	}
