385	public class Money {
386	    private static final int SCALE = 2;
387	
388	    public static BigDecimal round(BigDecimal value) {
389	        return value.setScale(SCALE, RoundingMode.HALF_EVEN);
390	    }
391	
392	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
393	        return round(a.multiply(b));
394	    }
395	
396	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
397	        return round(a.divide(b, SCALE, RoundingMode.HALF_EVEN));
398	    }
399	
400	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
401	        return round(a.subtract(b));
402	    }
403	
404	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
405	        return round(a.add(b));
406	    }
407	
408	    public static BigDecimal percentage(BigDecimal base, BigDecimal percent) {
409	        return multiply(base, divide(percent, BigDecimal.valueOf(100)));
410	    }
411	}
