418	public class Season {
419	    public static boolean isHighSeason(LocalDate date) {
420	        int month = date.getMonthValue();
421	        int day = date.getDayOfMonth();
422	
423	        if (month == 7) return true;
424	        if (month >= 1 && month <= 2) return true;
425	        if (month == 12 && day >= 15) return true;
426	
427	        return false;
428	    }
429	
430	    public static BigDecimal getSeasonMultiplier(LocalDate date) {
431	        if (isHighSeason(date)) {
432	            return BigDecimal.valueOf(1.20);
433	        }
434	        return BigDecimal.ONE;
435	    }
436	}

