 11	public class Database {
 12	    private static final Logger log = LoggerFactory.getLogger(Database.class);
 13	    private static HikariDataSource dataSource;
 14	
 15	    public static synchronized void initialize() throws SQLException {
 16	        if (dataSource != null) {
 17	            return;
 18	        }
 19	
 20	        String dbUrl = System.getenv("DB_URL");
 21	        String dbUser = System.getenv("DB_USER");
 22	        String dbPassword = System.getenv("DB_PASSWORD");
 23	
 24	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 25	            throw new IllegalStateException("Database configuration missing: DB_URL, DB_USER, DB_PASSWORD");
 26	        }
 27	
 28	        HikariConfig config = new HikariConfig();
 29	        config.setJdbcUrl(dbUrl);
 30	        config.setUsername(dbUser);
 31	        config.setPassword(dbPassword);
 32	        config.setMaximumPoolSize(10);
 33	        config.setMinimumIdle(2);
 34	
 35	        dataSource = new HikariDataSource(config);
 36	        log.info("Database connection pool initialized");
 37	
 38	        initializeSchema();
 39	    }
 40	
 41	    public static Connection getConnection() throws SQLException {
 42	        if (dataSource == null) {
 43	            throw new IllegalStateException("Database not initialized");
 44	        }
 45	        return dataSource.getConnection();
 46	    }
 47	
 48	    private static void initializeSchema() {
 49	        try (Connection conn = getConnection()) {
 50	            conn.setAutoCommit(false);
 51	            try {
 52	                String schema = """
 53	                    CREATE TABLE IF NOT EXISTS rooms (
 54	                        number INT PRIMARY KEY,
 55	                        type VARCHAR(50) NOT NULL,
 56	                        capacity INT NOT NULL,
 57	                        nightly_rate NUMERIC(10,2) NOT NULL
 58	                    );
 59	
 60	                    CREATE TABLE IF NOT EXISTS reservations (
 61	                        id BIGSERIAL PRIMARY KEY,
 62	                        room_number INT NOT NULL,
 63	                        guest_name VARCHAR(255) NOT NULL,
 64	                        guest_email VARCHAR(255) NOT NULL,
 65	                        guest_cpf VARCHAR(20) NOT NULL,
 66	                        check_in DATE NOT NULL,
 67	                        check_out DATE NOT NULL,
 68	                        guests INT NOT NULL,
 69	                        rate_plan VARCHAR(50) NOT NULL,
 70	                        company_code VARCHAR(50),
 71	                        nights INT NOT NULL,
 72	                        subtotal NUMERIC(10,2) NOT NULL,
 73	                        discount NUMERIC(10,2) NOT NULL,
 74	                        total NUMERIC(10,2) NOT NULL,
 75	                        status VARCHAR(20) NOT NULL,
 76	                        amount_paid NUMERIC(10,2) NOT NULL DEFAULT 0,
 77	                        refund NUMERIC(10,2),
 78	                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 79	                        FOREIGN KEY (room_number) REFERENCES rooms(number)
 80	                    );
 81	
 82	                    CREATE TABLE IF NOT EXISTS messages (
 83	                        id BIGSERIAL PRIMARY KEY,
 84	                        channel VARCHAR(50) NOT NULL,
 85	                        to_address VARCHAR(255) NOT NULL,
 86	                        subject VARCHAR(255) NOT NULL,
 87	                        body TEXT NOT NULL,
 88	                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 89	                    );
 90	
 91	                    CREATE INDEX IF NOT EXISTS idx_reservations_room_status
 92	                        ON reservations(room_number, status);
 93	                    CREATE INDEX IF NOT EXISTS idx_reservations_check_in_out
 94	                        ON reservations(check_in, check_out);
 95	                    """;
 96	
 97	                for (String statement : schema.split(";")) {
 98	                    String trimmed = statement.trim();
 99	                    if (!trimmed.isEmpty()) {
100	                        conn.createStatement().execute(trimmed);
101	                    }
102	                }
103	
104	                // Insert rooms if they don't exist
105	                conn.createStatement().execute(
106	                    "INSERT INTO rooms VALUES (101, 'STANDARD', 2, 249.90) ON CONFLICT DO NOTHING"
107	                );
108	                conn.createStatement().execute(
109	                    "INSERT INTO rooms VALUES (102, 'STANDARD', 2, 249.90) ON CONFLICT DO NOTHING"
110	                );
111	                conn.createStatement().execute(
112	                    "INSERT INTO rooms VALUES (201, 'DELUXE', 3, 389.90) ON CONFLICT DO NOTHING"
113	                );
114	                conn.createStatement().execute(
115	                    "INSERT INTO rooms VALUES (202, 'DELUXE', 3, 389.90) ON CONFLICT DO NOTHING"
116	                );
117	                conn.createStatement().execute(
118	                    "INSERT INTO rooms VALUES (301, 'SUITE', 4, 579.90) ON CONFLICT DO NOTHING"
119	                );
120	
121	                conn.commit();
122	                log.info("Database schema initialized");
123	            } catch (Exception e) {
124	                conn.rollback();
125	                throw e;
126	            }
127	        } catch (SQLException e) {
128	            log.error("Failed to initialize database schema", e);
129	            throw new RuntimeException(e);
130	        }
131	    }
132	
133	    public static void close() {
134	        if (dataSource != null) {
135	            dataSource.close();
136	        }
137	    }
